"""
Synapse Design System — Qt Stylesheet Generator

Generates QSS (Qt Style Sheets) from design tokens for the Synapse panel.
Houdini uses PySide2/Qt5 — all styles target that environment.

Usage:
    from synapse_styles import generate_stylesheet, STATUS_STYLES
    widget.setStyleSheet(generate_stylesheet())
"""

import sys
import os

# Allow importing tokens from the design directory
_design_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)))
if _design_dir not in sys.path:
    sys.path.insert(0, _design_dir)

from tokens import (
    SIGNAL, VOID, NEAR_BLACK, CARBON, GRAPHITE, SLATE, SILVER, BONE, WHITE,
    FIRE, GROW, WARN, ERROR,
    FONT_MONO, FONT_MONO_FALLBACKS, FONT_SANS, FONT_SANS_FALLBACKS,
    SIZE_LABEL, SIZE_SMALL, SIZE_UI, SIZE_BODY, SIZE_TITLE, SIZE_HERO,
    SPACE_XS, SPACE_SM, SPACE_MD, SPACE_LG,
    STATES,
)


def _font_family(primary, fallbacks):
    """Build a CSS font-family string."""
    fonts = [primary] + list(fallbacks)
    return ", ".join(f'"{f}"' for f in fonts)


MONO_FAMILY = _font_family(FONT_MONO, FONT_MONO_FALLBACKS)
SANS_FAMILY = _font_family(FONT_SANS, FONT_SANS_FALLBACKS)


def generate_stylesheet():
    """Generate the full QSS stylesheet for the Synapse panel."""
    return f"""
/* ═══════════════════════════════════════════════════════
   SYNAPSE DESIGN SYSTEM — Qt Stylesheet
   Generated from design tokens. Do not edit directly.
   ═══════════════════════════════════════════════════════ */

/* ── Base Panel ──────────────────────────────────────── */

QWidget#synapse_panel {{
    background-color: {NEAR_BLACK};
    color: {BONE};
    font-family: {SANS_FAMILY};
    font-size: {SIZE_BODY}px;
}}

/* ── Unified Header ──────────────────────────────────── */

QWidget#panel_header {{
    background-color: {VOID};
    border-bottom: 1px solid {GRAPHITE};
    min-height: 36px;
    max-height: 36px;
}}

QLabel#title_label {{
    color: {WHITE};
    font-family: {MONO_FAMILY};
    font-size: {SIZE_TITLE}px;
    font-weight: 600;
    letter-spacing: 2px;
}}

QLabel#status_dot {{
    font-size: 8px;
    min-width: 8px;
    max-width: 8px;
}}

QLabel#status_label {{
    color: {SILVER};
    font-family: {MONO_FAMILY};
    font-size: {SIZE_SMALL}px;
    letter-spacing: 1px;
}}

QLabel#status_detail {{
    color: {SLATE};
    font-family: {MONO_FAMILY};
    font-size: {SIZE_LABEL}px;
}}

QToolButton#overflow_button {{
    background-color: transparent;
    color: {SILVER};
    border: none;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_UI}px;
    padding: 2px {SPACE_SM}px;
    min-width: 28px;
}}

QToolButton#overflow_button:hover {{
    color: {WHITE};
    background-color: {GRAPHITE};
    border-radius: 3px;
}}

QToolButton#overflow_button::menu-indicator {{
    image: none;
}}

/* ── Overflow Menu ───────────────────────────────────── */

QMenu#overflow_menu {{
    background-color: {CARBON};
    color: {BONE};
    border: 1px solid {GRAPHITE};
    border-radius: 4px;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_SMALL}px;
    padding: {SPACE_XS}px 0px;
}}

QMenu#overflow_menu::item {{
    padding: {SPACE_SM}px {SPACE_MD}px;
}}

QMenu#overflow_menu::item:selected {{
    background-color: {GRAPHITE};
    color: {SIGNAL};
}}

/* ── Activity Log (collapsible) ──────────────────────── */

QFrame#activity_frame {{
    background-color: transparent;
    padding: 0px {SPACE_SM}px;
}}

QPushButton#activity_toggle {{
    background-color: transparent;
    color: {SLATE};
    border: none;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_LABEL}px;
    letter-spacing: 2px;
    padding: {SPACE_XS}px 0px;
    text-align: left;
}}

QPushButton#activity_toggle:hover {{
    color: {SILVER};
}}

QTextEdit#activity_log {{
    background-color: {VOID};
    color: {SILVER};
    border: 1px solid {GRAPHITE};
    border-radius: 4px;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_SMALL}px;
    padding: {SPACE_SM}px;
    max-height: 150px;
    selection-background-color: rgba(0, 212, 255, 0.3);
    selection-color: {WHITE};
}}

QScrollBar:vertical {{
    background-color: {VOID};
    width: 6px;
    margin: 0px;
}}

QScrollBar::handle:vertical {{
    background-color: {GRAPHITE};
    border-radius: 3px;
    min-height: 20px;
}}

QScrollBar::handle:vertical:hover {{
    background-color: {SLATE};
}}

QScrollBar::add-line:vertical,
QScrollBar::sub-line:vertical {{
    height: 0px;
}}

QScrollBar::add-page:vertical,
QScrollBar::sub-page:vertical {{
    background-color: transparent;
}}

/* ── Chat Input & Send (WhatsApp pill) ─────────────── */

QPlainTextEdit#chat_input {{
    background-color: {CARBON};
    color: {BONE};
    border: 1px solid {GRAPHITE};
    border-radius: 12px;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_BODY}px;
    padding: 8px {SPACE_MD}px;
    min-height: 36px;
}}

QPlainTextEdit#chat_input:focus {{
    border-color: {SLATE};
}}

QPushButton#send_button {{
    background-color: {SIGNAL};
    color: {VOID};
    border: none;
    border-radius: 18px;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_SMALL}px;
    font-weight: 600;
    padding: 10px 16px;
    min-width: 40px;
    min-height: 36px;
    max-height: 36px;
}}

QPushButton#send_button:hover {{
    background-color: #33DFFF;
}}

QPushButton#send_button:pressed {{
    background-color: #00A8CC;
}}

QPushButton#send_button:disabled {{
    color: {SLATE};
    border-color: {GRAPHITE};
}}

/* ── Connection Controls (compact footer) ────────────── */

QFrame#connection_frame {{
    background-color: {CARBON};
    border-top: 1px solid {GRAPHITE};
    padding: {SPACE_XS}px {SPACE_MD}px;
    min-height: 28px;
    max-height: 28px;
}}

QPushButton#connect_button {{
    background-color: transparent;
    color: {SIGNAL};
    border: 1px solid {SIGNAL};
    border-radius: 3px;
    font-family: {MONO_FAMILY};
    font-size: {SIZE_SMALL}px;
    padding: 2px {SPACE_SM}px;
    min-width: 72px;
}}

QPushButton#connect_button:hover {{
    background-color: rgba(0, 212, 255, 0.1);
}}

QPushButton#connect_button:pressed {{
    background-color: rgba(0, 212, 255, 0.2);
}}

QLabel#version_label {{
    color: {SLATE};
    font-family: {MONO_FAMILY};
    font-size: {SIZE_LABEL}px;
}}

QLabel#port_label {{
    color: {SLATE};
    font-family: {MONO_FAMILY};
    font-size: {SIZE_LABEL}px;
}}

/* ── Tooltip ─────────────────────────────────────────── */

QToolTip {{
    background-color: {CARBON};
    color: {BONE};
    border: 1px solid {GRAPHITE};
    font-family: {SANS_FAMILY};
    font-size: {SIZE_SMALL}px;
    padding: {SPACE_XS}px {SPACE_SM}px;
}}
"""


# ── Status-specific styles ──────────────────────────────

STATUS_STYLES = {}
for state_name, state_info in STATES.items():
    STATUS_STYLES[state_name] = f"""
        QLabel#status_dot {{ color: {state_info['color']}; }}
        QLabel#status_label {{ color: {state_info['color']}; }}
    """


# ── Convenience: animation keyframes as color tuples ────

STATUS_COLORS = {name: info["color"] for name, info in STATES.items()}


if __name__ == "__main__":
    print("=" * 50)
    print("  SYNAPSE QSS STYLESHEET")
    print("=" * 50)
    qss = generate_stylesheet()
    print(f"\nStylesheet length: {len(qss)} characters")
    print(f"Status styles: {list(STATUS_STYLES.keys())}")
    print("\n--- Preview (first 500 chars) ---")
    print(qss[:500])
    print("...")

    if len(self._msg_dedup) > 100:
        cutoff = now - 10.0
        self._msg_dedup = {
            k: v for k, v in self._msg_dedup.items() if v > cutoff
        }
    return True

# ── Status Management ────────────────────────────────

def _set_status(self, state, detail=""):
    """Update the status bar to reflect a new state."""
    self._status = state

    if _HAS_DESIGN and state in STATES:
        state_info = STATES[state]
        color = state_info["color"]
        label = state_info["label"]
    else:
        color = "#00D4FF"
        label = state.capitalize()

    self._status_label.setText(label)
    self._status_detail.setText(detail)

    if state == "executing":
        self._dot_animator.start(color)
    else:
        self._dot_animator.stop(color)
        self._dot_label.setStyleSheet(f"color: {color};")
        self._status_label.setStyleSheet(f"color: {color};")

    # Update connect button text
    if state in ("connected", "idle", "executing"):
        self._connect_btn.setText("Disconnect")
    else:
        self._connect_btn.setText("Connect")

def _on_dot_color(self, color):
    """Handle animated dot color change."""
    self._dot_label.setStyleSheet(f"color: {color};")

# ── WS Path Copy ─────────────────────────────────────

def _on_copy_ws_path(self):
    """Copy the WebSocket URL to clipboard."""
    if self._copy_text(_WS_URL):
        self._log_activity("Copied: {}".format(_WS_URL), "success")
    else:
        self._log_activity("Couldn't copy WS path to clipboard", "error")

@staticmethod
def _copy_text(text):
    """Copy text to clipboard via clip.exe (Windows) or Qt fallback."""
    import platform, subprocess
    if platform.system() == "Windows":
        try:
            p = subprocess.run(
                ["clip"], input=text.encode("utf-8"),
                creationflags=0x08000000, timeout=5,
            )
            return p.returncode == 0
        except Exception:
            pass
    try:
        app = QtWidgets.QApplication.instance() or QtGui.QGuiApplication.instance()
        if app:
            app.clipboard().setText(text)
            return True
    except Exception:
        pass
    return False

# ── Activity Log ─────────────────────────────────────

def _log_activity(self, message, level="info"):
    """Add a timestamped entry to the activity log."""
    timestamp = time.strftime("%H:%M:%S")

    color_map = {
        "info": SILVER if _HAS_DESIGN else "#999999",
        "success": GROW if _HAS_DESIGN else "#00E676",
        "warning": WARN if _HAS_DESIGN else "#FFAB00",
        "error": ERROR if _HAS_DESIGN else "#FF3D71",
        "action": SIGNAL if _HAS_DESIGN else "#00D4FF",
    }
    color = color_map.get(level, color_map["info"])

    html = (
        f'<span style="color: {SLATE if _HAS_DESIGN else "#555555"};">'
        f'{timestamp}</span> '
        f'<span style="color: {color};">{message}</span>'
    )
    self._log.append(html)

    # Trim if too long
    doc = self._log.document()
    if doc.blockCount() > _ACTIVITY_MAX_LINES:
        cursor = self._log.textCursor()
        cursor.movePosition(QtGui.QTextCursor.Start)
        cursor.movePosition(
            QtGui.QTextCursor.Down,
            QtGui.QTextCursor.KeepAnchor,
            doc.blockCount() - _ACTIVITY_MAX_LINES,
        )
        cursor.removeSelectedText()

# ── Tool Callbacks ───────────────────────────────────

def _on_project_setup(self):
    """Initialize project memory via shelf callback."""
    self._log_activity("Setting up project...", "action")
    self._set_status("executing", "Project setup")
    try:
        import synapse_shelf
        synapse_shelf.project_setup()
        self._log_activity("Project structure ready", "success")
        self._set_status("idle")
    except Exception as e:
        self._log_activity(f"Project setup hit a snag: {e}", "error")
        self._set_status("warning", str(e)[:40])

def _on_rag_folder(self):
    """Set RAG knowledge folder via shelf callback."""
    self._log_activity("Opening RAG folder picker...", "action")
    try:
        import synapse_shelf
        synapse_shelf.rag_folder()
        import os
        rag = os.environ.get("SYNAPSE_RAG_ROOT", "")
        if rag:
            self._log_activity("RAG folder: {}".format(rag), "success")
        else:
            self._log_activity("RAG folder cleared", "info")
    except Exception as e:
        self._log_activity("RAG folder setup: {}".format(e), "error")

def _on_inspect_selection(self):
    """Run inspect selection via shelf callback."""
    self._log_activity("Inspecting selection...", "action")
    try:
        import synapse_shelf
