        with open(self._FONT_ZOOM_PATH, "w", encoding="utf-8") as f:
            f.write(str(self._font_zoom))
    except OSError:
        pass

def _apply_font_zoom(self):
    """Apply stored zoom level to the chat display."""
    if self._font_zoom > 0:
        self._chat_display.zoomIn(self._font_zoom)
    elif self._font_zoom < 0:
        self._chat_display.zoomOut(abs(self._font_zoom))

